  fi
  case "${action,,}" in
      install|1) do_install ;;
      update|2) do_update ;;
      backup|3) do_backup ;;
      restore|4)
        if declare -f do_restore >/dev/null 2>&1; then
          do_restore
        else
          error "$(t error.unsupported_action "${APP_NAME:-app}" restore)"
        fi
        ;;
      cert|https)
        if declare -f do_cert >/dev/null 2>&1; then
