$(t app.blog.about_intro "$BLOG_AUTHOR")

$(t app.blog.about_body)

---

*$(t app.blog.about_footer)*
MD
success "$(t app.blog.about_created)"
fi
if [[ ! -f "${SITE_DIR}/content/page/archives/index.md" ]]; then
